#define NY_MODEL 15
#define NU_MODEL 15
static float sil_y_hist[NY_MODEL] = {0};
static float sil_u_hist[NU_MODEL] = {0};

static float simulate_narx(float u_atual) {
    for (int i = NU_MODEL - 1; i > 0; i--) sil_u_hist[i] = sil_u_hist[i-1];
    sil_u_hist[0] = u_atual;

    float y_k = 1.1990631745756126f * (sil_y_hist[0])
              + -0.05762015209762626f * (sil_y_hist[4])
              + -6.191075449735546e-06f * (sil_u_hist[1] * sil_u_hist[2])
              + 3.423043952840345e-05f * (sil_y_hist[0] * sil_y_hist[0])
              + -0.09824780304398335f * (sil_y_hist[6])
              + 6.448196680109485e-05f * (sil_u_hist[11] * sil_u_hist[12])
              + -0.04139135657366631f * (sil_y_hist[14])
              + -0.10664416467175378f * (sil_y_hist[2])
              + 1.119830856317376e-05f * (sil_u_hist[5] * sil_u_hist[6])
              + -3.121316371176042e-05f * (sil_y_hist[14] * sil_u_hist[1])
              + 2.1283726686910525e-05f * (sil_u_hist[0] * sil_u_hist[7])
              + 0.01648978481020207f * (sil_y_hist[12])
              + 0.0003455281871290548f * (sil_u_hist[4] * sil_u_hist[4])
              + 0.06339789806392998f * (sil_y_hist[5])
              + -0.00033465761267778343f * (sil_u_hist[3] * sil_u_hist[4])
              + 0.019753819379656135f * (sil_y_hist[8])
              + 0.00030831794773850487f * (sil_u_hist[3] * sil_u_hist[6])
              + -0.0002908414737785902f * (sil_u_hist[4] * sil_u_hist[6])
              + 0.0006597116840402803f * (sil_u_hist[2])
              + 1.2887598792686056e-05f * (sil_y_hist[0] * sil_u_hist[10]);

    for (int i = NY_MODEL - 1; i > 0; i--) sil_y_hist[i] = sil_y_hist[i-1];
    sil_y_hist[0] = y_k;
    return y_k;
}

static inline float relu(float x) { return (x > 0.0f) ? x : 0.0f; }

static float ann_predict(float *input) {
    float h1[128] = {0};
    float h2[128] = {0};
    float out = 0.0f;

    float norm_input[80];
    for (int i = 0; i < 80; i++) {
        norm_input[i] = (input[i] - scaler_mean[i]) / scaler_scale[i];
    }

    for (int i = 0; i < 128; i++) {
        float sum = b0[i];
        for (int j = 0; j < 80; j++) {
            sum += W0[i * 80 + j] * norm_input[j];
        }
        h1[i] = relu(sum);
    }

    for (int i = 0; i < 128; i++) {
        float sum = b1[i];
        for (int j = 0; j < 128; j++) {
            sum += W1[i * 128 + j] * h1[j];
        }
        h2[i] = relu(sum);
    }

    out = b2[0];
    for (int i = 0; i < 128; i++) {
        out += W2[i] * h2[i];
    }

    if (out > 80.0f) out = 80.0f;
    if (out < -10.0f) out = -10.0f;
    return out;
}

